def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in me if x == 'D')
    last_me, last_opp = history[-1]

    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    rl = 10 if n >= 10 else n
    recent = opp[n - rl:]
    recent_d = sum(1 for x in recent if x == 'D')

    if opp_d == 0:
        if n < 30:
            return 'C'
        if my_d < 5:
            return 'C' if last_me == 'D' else 'D'
        return 'D'

    hostile = False
    if opp_d * 2 >= n:
        hostile = True
    if rl >= 6 and recent_d * 2 >= rl:
        hostile = True
    if streak >= 3:
        hostile = True

    if hostile:
        if opp_c > opp_d and recent_d <= 3:
            if rng.random() < 0.05:
                return 'C'
        return 'D'

    if last_opp == 'D':
        provoked = False
        if n >= 2 and history[-2][0] == 'D':
            provoked = True
        if n >= 3 and history[-3][0] == 'D':
            provoked = True

        limit = 3 if n < 30 else max(3, n // 4)
        if streak <= 2 and provoked and recent_d <= 2 and opp_d <= limit:
            return 'C'

        if streak == 1 and recent_d == 1 and opp_d == 1:
            if rng.random() < 0.10:
                return 'C'

        return 'D'

    if last_opp == 'C':
        if recent_d == 0 and opp_d <= 2 and my_d >= 3:
            if rng.random() < 0.02:
                return 'D'
        return 'C'

    return 'C'
